function allSubsets(values) {
  const sorted = [...values].sort((a, b) => a - b)
  const result = []
  const path = []
  const explore = start => {
    result.push([...path])
    for (let i = start; i < sorted.length; i++) {
      path.push(sorted[i])
      explore(i + 1)
      path.pop()
    }
  }
  explore(0)
  return result
}
